\begin{theorem}
\tb If we have a commutative diagram:
\[
\begin{tikzcd}
0 \ar{r} & M \ar{r}{i} \ar{d}{\beta} & P \ar{r}{\sigma} \ar{d}{\alpha} & A \ar{r} \ar{d}{id} &0 \\
