  \draw[->] (P) to node  [right] {$\alpha$} (A);
  \draw[->] (A) to node [above] {$i'$} (C);
  \draw[->] (B) to node [right] {$\beta$} (C);
  \draw[->, bend left] (B) to node [above] {$\nu$} (P1);
  \draw[->, bend right] (A) to node [below] {$\mu $} (P1);
